sp_widget.client_script:
api.controller = function($scope, $window) {

    var c = this;


    // ==========================================================
    // VARIABLES
    // ==========================================================

    c.username = "";

    c.password = "";

    c.loading = false;

    c.errorMessage = "";


    // ==========================================================
    // LOGIN
    // ==========================================================

    c.login = function() {

        console.log("==========================================");
        console.log("CAMPUS LOGIN BUTTON CLICKED");
        console.log("==========================================");


        // ======================================================
        // CLEAR OLD ERROR
        // ======================================================

        c.errorMessage = "";


        // ======================================================
        // CHECK USERNAME
        // ======================================================

        if (!c.username) {

            console.log("LOGIN STOPPED: USERNAME IS EMPTY");

            c.errorMessage =
                "Please enter your username.";

            return;
        }


        // ======================================================
        // CHECK PASSWORD
        // ======================================================

        if (!c.password) {

            console.log("LOGIN STOPPED: PASSWORD IS EMPTY");

            c.errorMessage =
                "Please enter your password.";

            return;
        }


        // ======================================================
        // PRINT LOGIN DATA
        // ======================================================

        console.log("========== LOGIN DATA ==========");
        console.log("Username:", c.username);
        console.log("Password:", c.password);
        console.log("================================");


        // ======================================================
        // SHOW LOADING
        // ======================================================

        c.loading = true;

        console.log("LOGIN LOADING STARTED");


        // ======================================================
        // CREATE GLIDE AJAX
        // ======================================================

        console.log("Creating GlideAjax object...");

        var ga =
            new GlideAjax("x_snc_campus_foo_1.CampusLoginSessionUtils");

        console.log("GlideAjax object created successfully");


        // ======================================================
        // SCRIPT INCLUDE FUNCTION
        // ======================================================

        console.log("Sending sysparm_name = login");

        ga.addParam(
            "sysparm_name",
            "login"
        );


        // ======================================================
        // USERNAME
        // ======================================================

        console.log(
            "Sending username:",
            c.username
        );

        ga.addParam(
            "sysparm_username",
            c.username
        );


        // ======================================================
        // PASSWORD
        // ======================================================

        console.log(
            "Sending password:",
            c.password
        );

        ga.addParam(
            "sysparm_password",
            c.password
        );


        // ======================================================
        // CALL SCRIPT INCLUDE
        // ======================================================

        console.log("==========================================");
        console.log("CALLING SCRIPT INCLUDE...");
        console.log("Script Include: x_snc_campus_foo_1.CampusLoginSessionUtils");
        console.log("Function: login");
        console.log("Waiting for response...");
        console.log("==========================================");


        ga.getXMLAnswer(function(response) {

            console.log("==========================================");
            console.log("RESPONSE RECEIVED FROM SCRIPT INCLUDE");
            console.log("==========================================");

            console.log(
                "Raw Response:",
                response
            );


            // ==================================================
            // STOP LOADING
            // ==================================================

            c.loading = false;


            // ==================================================
            // NO RESPONSE
            // ==================================================

            if (!response) {

                console.log(
                    "ERROR: SCRIPT INCLUDE RETURNED NO RESPONSE"
                );

                c.errorMessage =
                    "Unable to connect to the login service.";

                $scope.$applyAsync();

                return;
            }


            // ==================================================
            // RESPONSE RECEIVED
            // ==================================================

            console.log(
                "Response is NOT empty."
            );


            // ==================================================
            // CONVERT RESPONSE TO OBJECT
            // ==================================================

            var result;


            try {

                console.log(
                    "Trying to parse JSON response..."
                );

                result =
                    JSON.parse(response);


                console.log(
                    "JSON PARSED SUCCESSFULLY"
                );

                console.log(
                    "Login Result Object:",
                    result
                );

            }

            catch (error) {

                console.log(
                    "JSON PARSE ERROR:",
                    error
                );

                c.errorMessage =
                    "Invalid response from login service.";

                $scope.$applyAsync();

                return;
            }


            // ==================================================
            // PRINT RECEIVED LOGIN DATA
            // ==================================================

            console.log("========== RECEIVED LOGIN DATA ==========");

            console.log(
                "Authentication:",
                result.authentication
            );

            console.log(
                "Session Number:",
                result.sessionNumber
            );

            console.log(
                "Session ID:",
                result.sessionId
            );

            console.log(
                "User Role:",
                result.userRole
            );

            console.log(
                "User Name:",
                result.userName
            );

            console.log(
                "User Sys ID:",
                result.user
            );

            console.log("=========================================");


            // ==================================================
            // CHECK AUTHENTICATION
            // ==================================================

            if (
                result.authentication === true
            ) {

                console.log(
                    "AUTHENTICATION SUCCESSFUL"
                );


                // ==============================================
                // CREATE LOGIN OBJECT
                // ==============================================

                var campusLogin = {

                    authentication:
                        result.authentication,

                    sessionNumber:
                        result.sessionNumber,

                    sessionId:
                        result.sessionId,

                    userRole:
                        result.userRole,

                    userName:
                        result.userName,

                    user:
                        result.user

                };


                console.log(
                    "Campus Login Object:",
                    campusLogin
                );


                // ==============================================
                // STORE IN LOCAL STORAGE
                // ==============================================

                localStorage.setItem(
                    "campusLogin",
                    JSON.stringify(campusLogin)
                );

                console.log(
                    "Campus Login Object stored in localStorage"
                );


                // ==============================================
                // ROLE BASED REDIRECTION
                // ==============================================

                if (
                    result.userRole === "Student"
                ) {

                    console.log(
                        "Redirecting to Student Dashboard"
                    );

                    $window.location.href ="https://ltm-hck-2876-0046.lab.service-now.com/food_services?id=food_service_student_dashbaord_page";

                    return;
                }


                if (
                    result.userRole === "Staff"
                ) {

                    console.log(
                        "Redirecting to Staff Dashboard"
                    );

                    $window.location.href =
                        "https://ltm-hck-2876-0046.lab.service-now.com/food_services?id=food_services_staff_dashboard_page";

                    return;
                }


                if (
                    result.userRole === "Admin"
                ) {

                    console.log(
                        "Redirecting to Admin Dashboard"
                    );

                    $window.location.href =
                        "https://ltm-hck-2876-0046.lab.service-now.com/food_services?id=food_service_admin_dashboard_page";

                    return;
                }


                if (
                    result.userRole === "Manager"
                ) {

                    console.log(
                        "Redirecting to Manager Dashboard"
                    );

                    $window.location.href =
                        "https://ltm-hck-2876-0046.lab.service-now.com/food_services?id=food_service_manager_dashboard_page";

                    return;
                }


                // ==============================================
                // UNKNOWN ROLE
                // ==============================================

                console.log(
                    "ERROR: UNKNOWN USER ROLE:",
                    result.userRole
                );

                c.errorMessage =
                    "No dashboard is configured for this role.";

                $scope.$applyAsync();

            }

            else {

                console.log(
                    "AUTHENTICATION FAILED"
                );

                console.log(
                    "Authentication value:",
                    result.authentication
                );


                // ==============================================
                // AUTHENTICATION FAILED
                // ==============================================

                c.errorMessage =
                    "Invalid username or user access.";

                $scope.$applyAsync();

            }

        });


        // ======================================================
        // IMPORTANT
        // ======================================================

        console.log(
            "GlideAjax request has been sent."
        );

        console.log(
            "NOW WAITING FOR SCRIPT INCLUDE RESPONSE..."
        );

    };


    // ==========================================================
    // ENTER KEY
    // ==========================================================

    c.checkEnter = function(event) {

        if (
            event.keyCode === 13
        ) {

            console.log(
                "ENTER KEY PRESSED - STARTING LOGIN"
            );

            c.login();

        }

    };

};

sp_widget.css:
.cfa-login-page {
min-height: 100vh;
background: #f1f5f9;

display: flex;
align-items: center;
justify-content: center;

padding: 30px;
}

.cfa-login-card {
width: 100%;
max-width: 1000px;

min-height: 580px;

background: #ffffff;

border-radius: 18px;

overflow: hidden;

display: flex;

box-shadow:
0 20px 50px rgba(15, 23, 42, 0.12);
}

/* ========================================================= */
/* LEFT LOGIN SECTION */
/* ========================================================= */

.cfa-login-form-section {
width: 55%;

padding: 55px 60px;

display: flex;
flex-direction: column;

justify-content: center;
}

/* BRAND */

.cfa-login-brand {
display: flex;
align-items: center;

gap: 9px;

font-size: 20px;
font-weight: 800;

color: #0f172a;

margin-bottom: 55px;
}

.cfa-login-brand b {
color: #0d9488;
}

.cfa-login-logo {
font-size: 25px;
}

/* HEADING */

.cfa-login-heading h1 {
margin: 0 0 10px 0;

font-size: 32px;

font-weight: 800;

color: #0f172a;
}

.cfa-login-heading p {
margin: 0 0 35px 0;

color: #64748b;

font-size: 14px;

line-height: 1.6;
}

/* FORM */

.cfa-login-form {
width: 100%;
}

.cfa-form-group {
margin-bottom: 22px;
}

.cfa-form-group label {
display: block;

margin-bottom: 8px;

color: #334155;

font-size: 13px;

font-weight: 700;
}

/* INPUT */

.cfa-input-wrapper {
position: relative;
}

.cfa-input-icon {
position: absolute;

left: 14px;

top: 50%;

transform: translateY(-50%);

font-size: 16px;
}

.cfa-input-wrapper input {
width: 100%;

height: 48px;

border: 1px solid #cbd5e1;

border-radius: 9px;

padding: 0 15px 0 45px;

font-size: 14px;

color: #0f172a;

outline: none;

box-sizing: border-box;

transition: 0.2s;
}

.cfa-input-wrapper input:focus {
border-color: #0d9488;

box-shadow:
0 0 0 3px rgba(13, 148, 136, 0.10);
}

.cfa-input-wrapper input::placeholder {
color: #94a3b8;
}

/* ERROR */

.cfa-login-error {
background: #fef2f2;

border: 1px solid #fecaca;

color: #dc2626;

padding: 11px 13px;

border-radius: 8px;

font-size: 13px;

margin-bottom: 18px;
}

/* LOGIN BUTTON */

.cfa-login-button {
width: 100%;

height: 48px;

border: none;

border-radius: 9px;

background: #0d9488;

color: #ffffff;

font-size: 14px;

font-weight: 700;

cursor: pointer;

transition: 0.2s;
}

.cfa-login-button:hover {
background: #0f766e;
}

.cfa-login-button:disabled {
opacity: 0.65;

cursor: not-allowed;
}

/* BACK HOME */

.cfa-back-home {
margin-top: 28px;

text-align: center;
}

.cfa-back-home a {
color: #0d9488;

text-decoration: none;

font-size: 13px;

font-weight: 600;
}

.cfa-back-home a:hover {
text-decoration: underline;
}

/* ========================================================= */
/* RIGHT INFORMATION SECTION */
/* ========================================================= */

.cfa-login-info {
width: 45%;

background: #0f172a;

color: #ffffff;

display: flex;

align-items: center;

justify-content: center;

padding: 50px;
}

.cfa-login-info-content {
max-width: 330px;

text-align: center;
}

.cfa-food-icon {
font-size: 55px;

margin-bottom: 25px;
}

.cfa-login-info h2 {
margin: 0 0 15px 0;

font-size: 27px;

font-weight: 800;
}

.cfa-login-info p {
margin: 0;

color: #cbd5e1;

font-size: 14px;

line-height: 1.7;
}

/* FEATURES */

.cfa-login-features {
margin-top: 35px;

text-align: left;
}

.cfa-feature {
display: flex;

align-items: center;

gap: 10px;

margin-bottom: 15px;

color: #cbd5e1;

font-size: 13px;
}

.cfa-feature span:first-child {
color: #2dd4bf;

font-weight: 800;

font-size: 16px;
}

/* ========================================================= */
/* RESPONSIVE */
/* ========================================================= */

@media (max-width: 800px) {

.cfa-login-card {
max-width: 500px;
}

.cfa-login-form-section {
width: 100%;


padding: 45px 35px;


}

.cfa-login-info {
display: none;
}

}

@media (max-width: 480px) {

.cfa-login-page {
padding: 15px;
}

.cfa-login-form-section {
padding: 35px 25px;
}

.cfa-login-heading h1 {
font-size: 27px;
}

}
